 return `<section aria-labelledby="sourceAuditTitle"><h2 id="sourceAuditTitle">Luna source checks · ${esc(a.checkedAt)}</h2><p>${s.liveAttempted} websites attempted live · ${s.excluded} blacklist exclusions · ${s.neededEasierPrompts} needed easier prompts · ${s.revisedGuides} guides revised.</p><p>${s.usable} usable · ${s.partial} partial · ${s.blocked} blocked · ${s.unavailable} unavailable · ${s.retested} routes retested.</p><p class="muted">${esc(a.limits)}</p><div class="prompt-actions">${docLink('AUDIT.md','Full source audit')}<a href="source-guides/source-audit.json" download>Download audit JSON</a><a href="prompts/check-one-source.md" target="_blank">Short source-check prompt</a></div><div class="audit-filters"><label class="search"><input id="auditSearch" placeholder="Search source checks" aria-label="Search source checks"></label><label>Show <select id="auditFilter"><option value="all">All sources</option><option value="revised">Revised guides</option><option value="needs-easier">Needed easier prompts</option><option value="access">Blocked or unavailable</option><option value="easy">Already easy</option><option value="excluded">Blacklist exclusions</option></select></label><span id="auditResultCount" role="status">${s.websites} sources</span></div><div class="table-scroll"><table id="sourceAuditTable"><thead><tr><th>Website / guide</th><th>Original instructions</th><th>Live result</th><th>Method</th><th>Finding</th></tr></thead><tbody>${a.sources.map(r=>`<tr data-audit-search="${esc([r.domain,r.issue,r.recommendedNextStep].join(' ').toLowerCase())}" data-audit-changed="${r.changed}" data-audit-needs="${r.needsEasierPrompt}" data-audit-assessment="${esc(r.promptAssessment)}" data-audit-outcome="${esc(r.outcome)}"><td>${docLink(r.guide,r.domain)}</td><td>${esc(({easy:'Already easy',needs_simplification:'Needed simplification',missing:'Missing instructions',not_applicable:'Excluded'})[r.promptAssessment])}${r.changed?'<br>Guide revised':''}</td><td>${esc(r.outcome)}</td><td>${esc(r.bestMethod)}</td><td><details class="audit-finding"><summary>${esc(r.issue)}</summary>${r.quickStart.length?`<ol>${r.quickStart.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`:''}${r.attempts.map(t=>`<p>${link(t.url,t.method)}: ${esc(t.result)}${Object.keys(t.observedFields).length?'<br>'+Object.entries(t.observedFields).map(([k,v])=>esc(k)+': '+esc(v??'Unknown')).join(' · '):''}${t.error?'<br>'+esc(t.error):''}</p>`).join('')}<p><strong>Next step:</strong> ${esc(r.recommendedNextStep)}</p><p class="muted">${r.retested?'Route retested in this audit.':'No route retest recorded.'}</p></details></td></tr>`).join('')}</tbody></table></div></section>`;
