function filterSourceAudit(){
 const search=$('#auditSearch'),select=$('#auditFilter');if(!search||!select)return;
 const q=search.value.trim().toLowerCase(),filter=select.value,rows=$$('[data-audit-search]');let count=0;
 for(const row of rows){const d=row.dataset,match=filter==='all'||(filter==='revised'&&d.auditChanged==='true')||(filter==='needs-easier'&&d.auditNeeds==='true')||(filter==='access'&&['blocked','unavailable'].includes(d.auditOutcome))||(filter==='easy'&&d.auditAssessment==='easy')||(filter==='excluded'&&d.auditOutcome==='excluded');row.hidden=!(match&&d.auditSearch.includes(q));if(!row.hidden)count++;}
 $('#auditResultCount').textContent=`${count} ${count===1?'source':'sources'}`;
}
