 $('#customBlacklist').innerHTML=profile.customKeywords.map((s,i)=>`<p class="blacklist-keyword">${esc(s)} <button data-remove-keyword="${i}" aria-label="Remove blacklist keyword ${esc(s)}">Remove</button></p>`).join('');
 const ideas=data.ideas.filter(i=>!allowed(i)),events=data.events.filter(e=>!allowed(e));$('#blacklistSummary').textContent=`Hidden archive · ${ideas.length} ideas · ${events.filter(e=>e.status==='dated').length} dated listings`;
 $('#blacklistArchive').innerHTML='<p class="muted">Research is retained so these subjects are not rediscovered accidentally. They do not appear in active views or exports.</p>'+ideas.map(i=>`<p>${activityIcon(i)} <strong>${esc(i.name)}</strong> · ${esc(blacklistReason(i,profile))}</p>`).join('');
