function collectionOutcome(value){return ({success:'Fetched · candidates found',no_matches:'Fetched · no matches',deferred_rate_limit:'Deferred · crawl delay',robots_disallowed:'Blocked by robots.txt',robots_unavailable:'Robots check failed',http_error:'HTTP error',fetch_error:'Fetch failed',parser_error:'Parser failed',unexpected_content:'Unexpected content',configuration_error:'Configuration error',not_run:'Not run'})[value]||value||'Not run';}
function renderSourcePriorities(p){
 if(!p)return '<p>Source priorities have not been built yet.</p>';
 const labels={code_verified:'Code extracted leads',code_unverified:'Code not yet verified',unassessed_for_code:'Code route unassessed',historical_luna_candidate:'Historical Luna candidate',unresolved_access_or_coverage:'Access or coverage unresolved'};
 const renderRows=(rows)=>`<ol class="priority-list">${rows.map(x=>`<li><strong>${x.entryUrls.length?link(x.entryUrls[0],x.domain):esc(x.domain)}</strong> · ${esc(labels[x.classification]||x.classification)}${x.guide?' · '+docLink(x.guide,'Guide'):''}<p>${esc(x.nextAction)}</p>${x.focusReason?`<p class="muted">${esc(x.focusReason)}</p>`:''}${x.evidence?`<p class="muted">${esc(x.evidence)}</p>`:''}<p class="muted">${x.historicalDatedEvents} historical dated listings · ${x.referenceCount} saved links${x.audit?' · Luna audit '+esc(x.audit.checkedAt)+' ('+esc(x.audit.outcome)+')':''}</p></li>`).join('')}</ol>`;
 const sections=[['deterministic','1. Run configured code collectors'],['code_assessment','Assess more sources for code'],['luna','2. Luna fallback candidates'],['harder','3. Harder or access-limited cases']].map(([key,title])=>`<details class="priority-queue" ${key==='deterministic'?'open':''}><summary>${esc(title)} · ${p.queues[key].length}</summary>${renderRows(p.queues[key])}</details>`).join('');
 const discovery=p.discovery.map(x=>`<li><strong>${esc(x.title)}</strong><p>${esc(x.steps)}</p></li>`).join('');
 return `<section class="priority-section" aria-labelledby="priorityTitle"><h2 id="priorityTitle">Research order</h2><p>Use code first, then Luna for unresolved extraction, then stronger review or an authorized browser for genuinely harder cases.</p><p class="muted">Queues overlap. A Luna candidate has a historical spot check; it is not proof that code will fail. Historical event counts include past dates and may include duplicates. Respect rate limits and access restrictions.</p><p>${docLink('priorities.md','Priority and discovery guide')} · <a href="prompts/discover-sources.md" target="_blank">New-source discovery prompt</a></p>${sections}<details class="priority-queue"><summary>Discover new sources · ${p.discovery.length} methods</summary><ol class="priority-list">${discovery}</ol></details></section>`;
}
function renderCollection(){
 const c=data.collectionStatus,el=$('#collectionStatus');if(!c){el.innerHTML='<p>Collection status has not been built yet.</p>';return;}
 const s=c.summary;
 const endpoints=c.endpoints.map(e=>{const a=e.lastAttempt,state=a?.outcome||'not_run',candidateRun=state==='success'?a:e.lastSuccess;const cs=candidateRun?.candidates||[];
 const latestLabel=state==='success'&&a?.method==='deterministic-cache-reparse'?'Reparsed cached page · candidates found':collectionOutcome(state);
 const candidates=cs.map(x=>`<li>${link(x.url,x.title||x.url)} <span class="muted">${x.date?esc(x.date)+(x.startTime?' · '+esc(x.startTime)+(x.endTime?'–'+esc(x.endTime):''):'')+(x.priceText?' · '+esc(x.priceText):'')+(x.inWindow===false?' · outside selected window':''):(x.kind==='article_lead'?'Article lead':x.kind==='activity_lead'?'Activity lead':'Event-page lead')+' · event date unverified'+(x.scheduleText?' · source text: '+esc(x.scheduleText):'')+(x.publishedAt?' · published '+esc(x.publishedAt.slice(0,10)):'')}</span></li>`).join('');
 const attempts=e.recentAttempts.map(x=>`<li>${esc(x.startedAt)} · ${esc(x.method||'unknown method')} · ${esc(x.method==='deterministic-cache-reparse'&&x.outcome==='success'?'Reparsed cached page · candidates found':collectionOutcome(x.outcome))} · ${x.candidateCount} candidates${x.httpStatus?' · HTTP '+esc(x.httpStatus):''}${x.message?' · '+esc(x.message):''}</li>`).join('');
 return `<article class="collection-endpoint collection-${esc(state)}"><h3>${link(e.url,e.name)}</h3><p><strong>${esc(latestLabel)}</strong> · ${esc(a?.method||e.method)}${a?' · '+esc(a.startedAt):''}</p><p>${a?`${a.candidateCount} candidate links · ${a.datedInWindow} dated within ${esc(a.windowStart)}–${esc(a.windowEnd)}${a.undatedCandidates?' · '+a.undatedCandidates+' dates unverified':''}`:'No collection attempt yet.'}${e.lastSuccessAt?` · Last successful fetch: ${esc(e.lastSuccessAt)}`:''}</p><p class="muted">${esc(e.note)} ${esc(a?.message||'')}</p>${cs.length?`<details><summary>Candidate links · ${cs.length} · ${state==='success'?'latest run':'last successful run'}</summary><p class="muted">Unreviewed source leads from a page fetched ${esc(candidateRun.sourceFetchedAt||candidateRun.startedAt)}, not calendar events. Article publication dates are not event dates.</p><ul>${candidates}</ul></details>`:''}${attempts?`<details><summary>Recent attempts</summary><ul>${attempts}</ul></details>`:''}</article>`}).join('');
 const websites=c.websites.map(w=>{const h=w.historicalAudit, refs=w.references.map(r=>`<li>${link(r.url,r.title)} <span class="muted">${esc(r.kind)}</span>${(r.heldContexts||[]).map(x=>`<p class="muted">Held: ${esc(x.reason||'Review needed')} · ${esc(x.researchFile)}</p>`).join('')}${(r.discoveryContexts||[]).map(x=>`<p class="muted">Source proposal: ${esc(x.methodObserved)} · ${esc(x.nextStep||'Review needed')} · ${esc(x.researchFile)}</p>`).join('')}</li>`).join('');const hist=h?`${h.outcome} · ${h.method} · ${h.checkedAt}`:'No historical audit';return `<details class="source-row collection-site" data-collection-search="${esc([w.domain,...w.references.flatMap(r=>[r.title,...(r.heldContexts||[]).flatMap(x=>[x.title,x.reason]),...(r.discoveryContexts||[]).flatMap(x=>[x.title,x.nextStep])])].join(' ').toLowerCase())}" data-collection-route="${w.configuredSources.length?'configured':'unassessed'}" data-collection-audit="${esc(h?.outcome||'none')}" data-collection-method="${esc(h?.method||'none')}"><summary><strong>${esc(w.domain)}</strong> <span class="muted">${w.references.length} links · ${esc(w.routeAssessment)}</span></summary><p>Historical research: ${w.historicalPrimaryEvents} dated events attributed here. ${esc(hist)}.</p>${h?.issue?`<p class="muted">${esc(h.issue)}</p>`:''}<p>${w.guide?docLink(w.guide,'Source guide'):'No guide yet'} · ${w.evidenceUrls} recorded evidence links · ${w.leadUrls} research or idea links</p>${refs?`<ul>${refs}</ul>`:'<p class="muted">No saved URL in the source inventory.</p>'}</details>`}).join('');
 const refreshes=(c.recentRefreshes||[]).map(r=>`<details class="source-row"><summary>${esc(r.startedAt)} · ${esc(r.outcome)} · ${r.candidateCount} leads · ${r.eventsAdded} added</summary><p>${esc(r.windowStart)}–${esc(r.windowEnd)} · Luna: ${esc(r.luna.status)} (${r.luna.queued} queued) · Terra: ${esc(r.terra.status)} · publication: ${esc(r.publication)}</p><p class="muted">${esc(r.message)}</p><ul>${r.sources.map(x=>`<li>${esc(x.name||x.sourceId)} · ${esc(x.outcome)} · ${x.candidateCount} leads${x.message?' · '+esc(x.message):''}</li>`).join('')}</ul></details>`).join('');
 el.innerHTML=`<h2>Recent refreshes</h2>${refreshes||'<p>No on-demand refreshes recorded yet.</p>'}<p>${s.configuredSources} collection entry points · ${s.success} latest runs found candidates · ${s.noMatches} no matches · ${s.deferred} deferred · ${s.failed} failed · ${s.notRun} not run.</p><p class="muted">Collection is started manually. A successful fetch is not proof an event can be attended. Raw pages and detailed candidate files stay on the machine that collected them.</p><p>${docLink('collection.md','How collection and review work')}</p>${renderSourcePriorities(data.sourcePriority)}<h2>Configured sources</h2>${endpoints||'<p>No sources configured.</p>'}<h2>All known websites</h2><p class="muted">${s.websites} websites · ${s.referenceUrls} saved links · ${s.historicAuditSites} websites in the historical audit. “Not assessed” does not mean that a model or browser is required.</p><div class="audit-filters"><label class="search"><input id="collectionSearch" placeholder="Search websites and leads" aria-label="Search websites and leads"></label><label>Show <select id="collectionFilter"><option value="all">All websites</option><option value="configured">Code collector configured</option><option value="unassessed">Not assessed for automation</option><option value="browser">Historical browser checks</option><option value="access">Historical access problems</option></select></label><span id="collectionCount" role="status">${s.websites} websites</span></div><div id="collectionSites">${websites}</div>`;
}
function filterCollection(){const q=$('#collectionSearch')?.value.trim().toLowerCase()||'',f=$('#collectionFilter')?.value||'all';let count=0;for(const row of $$('[data-collection-search]')){const d=row.dataset;const match=f==='all'||f===d.collectionRoute||(f==='browser'&&['desktop-browser','android-firefox','android-app'].includes(d.collectionMethod))||(f==='access'&&['blocked','unavailable'].includes(d.collectionAudit));row.hidden=!(match&&d.collectionSearch.includes(q));if(!row.hidden)count++;}const n=$('#collectionCount');if(n)n.textContent=`${count} ${count===1?'website':'websites'}`;}
function renderReport(){const r=data.report;if(!r){$('#researchReport').innerHTML='<p>Report is being prepared.</p>';return;}const s=r.summary;$('#researchReport').innerHTML=`<p>Historical research totals, including past dates: ${s.allowedDated} allowed dated listings · ${s.preferredDated} at preferred times · ${s.offers} allowed undated options. ${s.newDated} new dated listings across ${s.roundCount} research rounds.</p><div class="prompt-actions"><button id="downloadReport">Download report JSON</button>${docLink('REPORT.md','Report as Markdown')}${docLink('README.md','Source guide index')}</div>${renderSourceAudit()}<h2>Website yield</h2><p class="muted">Dated counts assign each occurrence to one primary source website. Supporting citations can overlap. Counts use the saved default profile; browser preference changes do not rewrite this research snapshot.</p><div class="table-scroll"><table><thead><tr><th>Website</th><th>Raw dated</th><th>New</th><th>Preferred</th><th>Raw drop-ins</th><th>Observed methods</th><th>Instructions</th></tr></thead><tbody>${r.websites.map(w=>`<tr><td>${link(w.entryUrl,w.domain)}</td><td>${w.primaryEvents}</td><td>${w.newEvents}</td><td>${w.primaryPreferred}</td><td>${w.offers}</td><td>${esc(w.methods.join(', '))}</td><td>${docLink(w.guide,'Guide')}</td></tr>`).join('')}</tbody></table></div><details class="report-ideas"><summary>Every research note · ${r.ideas.length} coverage records</summary><label class="search source-search"><input id="reportIdeaSearch" placeholder="Search idea coverage" aria-label="Search idea coverage"></label><p class="muted">Counts use explicit idea links or exact normalized venue names. Generic source-index links receive no event credit. Zero means no linked verified record, not proof that no events exist. Idea counts may overlap.</p><div class="table-scroll"><table><thead><tr><th>Idea</th><th>Status</th><th>Dated</th><th>Preferred</th><th>Drop-ins</th><th>Websites / next step</th></tr></thead><tbody>${r.ideas.map(i=>`<tr data-report-idea="${esc(i.name.toLowerCase())}"><td>${esc(i.name)}</td><td>${esc(i.status)}</td><td>${i.events}</td><td>${i.preferredEvents}</td><td>${i.offers}</td><td>${esc(i.websites.join(', ')||i.nextStep||'Research needed')}</td></tr>`).join('')}</tbody></table></div></details><h2>Research rounds</h2>${r.rounds.map(round=>`<details class="source-row"><summary>${esc(round.id)} · ${round.newDated} new dates · ${round.preferredNew} preferred</summary><p>${esc(round.summary||'')}</p><ul>${round.attempts.map(a=>`<li><strong>${esc(a.website)}</strong> · ${esc(a.method)}: ${esc(a.result)}</li>`).join('')}</ul></details>`).join('')}`;}
async function start(){try{const r=await fetch('./data.json');if(!r.ok)throw Error('Could not load activity research');data=await r.json();const requestedDay=new URLSearchParams(location.search).get('day'),requested=requestedWeek(data.meta);if(validDay(requestedDay)){day=requestedDay;week=mondayOf(day);}else if(requested){week=requested;day='all';}profile=normalizeProfile(storedProfile||data.preferences||DEFAULT_PROFILE);$('#timeFilter').value=profile.timeMode;renderCategoryOptions();renderCoverage();renderWeek();renderIdeas();persistSaved();switchTab(location.hash.slice(1));fetch('./prompts/discover-more.md').then(r=>{if(!r.ok)throw Error();return r.text();}).then(t=>{prompt=t;$('#promptText').textContent=t;}).catch(()=>$('#promptText').textContent='Prompt could not load. Use the download link or reload.');}catch(err){$('#eventList').innerHTML=`<div class="empty"><strong>Research could not load.</strong><p>${esc(err.message)}. Reload this page to try again.</p></div>`;}}
