function connectionStatus(){const el=$('#connectionStatus');el.hidden=navigator.onLine;el.textContent='Offline · saved research. Recheck prices and places when online.';}
window.addEventListener('online',connectionStatus);window.addEventListener('offline',connectionStatus);connectionStatus();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{const offerUpdate=()=>{if(reg.waiting&&navigator.serviceWorker.controller){$('#updateApp').hidden=false;$('#updateApp').onclick=()=>reg.waiting?.postMessage({type:'SKIP_WAITING'});}};offerUpdate();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',offerUpdate));}).catch(()=>{});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing&&navigator.serviceWorker.controller&&$('#updateApp').hidden===false){refreshing=true;location.reload();}});}
// Re-evaluate past dates after midnight or returning to an installed app.
let displayedToday=localDate();function refreshDate(){const today=localDate();if(data&&today!==displayedToday){if(day===displayedToday){day=today;week=mondayOf(day);}displayedToday=today;renderCoverage();renderWeek();persistSaved();}}
setInterval(refreshDate,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDate();});
